#!/usr/bin/env node
/**
 * One process, one nullifier binding. Prints the wallet the registry says owns
 * the (scope, nullifier) pair.
 *
 * A fresh PROCESS is required here, not merely a fresh registry instance. The
 * bug this fixture exists to catch wrote its binding onto the global `Object`
 * rather than into the file, and a second instance in the SAME process reads
 * that pollution straight back and answers correctly — so an in-process
 * "restart" test passes against the broken code and proves nothing. Only a new
 * process starts with a clean `Object`.
 *
 * Prints the winning wallet, or ERR:<message>. `String()` because a registry
 * that reached an inherited property can return a Function where an address
 * belongs, and that should be visible in the assertion rather than a crash.
 */
import { PersistentNullifierRegistry } from '../dist/persistent-nullifier-registry.js';

const [base, scope, nullifier, wallet] = process.argv.slice(2);
const registry = new PersistentNullifierRegistry({ base });

try {
  process.stdout.write(String(await registry.bind(scope, nullifier, wallet)));
} catch (err) {
  process.stdout.write(`ERR:${err.message}`);
}
